import { LABEL_ALIGNMENT } from '../constants.js';
import { LabelAlignment } from '../types/range-legend.internal.js';

const DEFAULT_POSITION_Y_HORIZONTAL = 22;

export const getHorizontalLabelPosition = (
  labelWidth: number,
  itemStartPosition: number,
  segmentSize: number,
  alignment: LabelAlignment,
) => {
  const labelPositionY = DEFAULT_POSITION_Y_HORIZONTAL;

  switch (alignment) {
    case LABEL_ALIGNMENT.START:
      return {
        labelPositionX: Math.floor(itemStartPosition - labelWidth / 2),
        labelPositionY,
      };
    case LABEL_ALIGNMENT.END: {
      return {
        labelPositionX: Math.floor(
          itemStartPosition + segmentSize - labelWidth / 2,
        ),
        labelPositionY,
      };
    }
    case LABEL_ALIGNMENT.CENTER: {
      return {
        labelPositionX: Math.floor(
          itemStartPosition + segmentSize / 2 - labelWidth / 2,
        ),
        labelPositionY,
      };
    }
  }
};
